<?php declare(strict_types=1);

namespace App\Entity;

use App\ApiResource\Traits\TimestampableTrait;
use App\Enum\CardListType;
use App\Repository\CardListRepository;
use Doctrine\Common\Collections\ArrayCollection;
use Doctrine\Common\Collections\Collection;
use Doctrine\ORM\Mapping as ORM;
use Symfony\Component\Uid\Uuid;

/**
 * A named collection or wishlist owned by a {@see User}. A user can have any number of each.
 *
 * The id is generated by the client rather than the server, so a list created while offline can
 * already be referenced by queued entry changes before it has been synced.
 */
#[ORM\Entity(repositoryClass: CardListRepository::class)]
#[ORM\Table(name: 'card_list')]
#[ORM\Index(name: 'idx_card_list_user_type', columns: ['user_id', 'type'])]
#[ORM\HasLifecycleCallbacks]
class CardList
{
    use TimestampableTrait;

    #[ORM\Id]
    #[ORM\Column(type: 'uuid', unique: true)]
    public private(set) Uuid $id;

    #[ORM\ManyToOne(targetEntity: User::class)]
    #[ORM\JoinColumn(name: 'user_id', referencedColumnName: 'id', nullable: false, onDelete: 'CASCADE')]
    public private(set) User $user;

    #[ORM\Column(type: 'string', length: 20, enumType: CardListType::class)]
    public private(set) CardListType $type;

    #[ORM\Column(type: 'string', length: 100)]
    public string $name {
        get => $this->name;
        set => $this->name = $value;
    }

    /** @var Collection<int, CardListEntry> */
    #[ORM\OneToMany(targetEntity: CardListEntry::class, mappedBy: 'list')]
    public private(set) Collection $entries;

    public function __construct(Uuid $id, User $user, CardListType $type, string $name)
    {
        $this->id = $id;
        $this->user = $user;
        $this->type = $type;
        $this->name = $name;
        $this->entries = new ArrayCollection();
        $this->initializeTimestamps();
    }
}
